unitsize(6mm);
defaultpen(linewidth(.7pt)+fontsize(8pt));

real r=2*sqrt(3);

pair A=r*dir(0), B=r*dir(60), C=r*dir(180);
pair F=foot(B,A,C);

draw((A+B+C)--((A+B+C)/2),Arrows(4));
draw(A--B--C--cycle,dotted);
draw(A--F);

label("$A$",A,S);
label("$B$",B,S);
label("$C$",C,S);
label("$F$",F,S);
draw(rightanglemark(A,B,C,8));
draw(rightanglemark(A,F,C,8));
draw(rightanglemark(C,F,B,8));
draw(rightanglemark(B,C,F,8));
[/asy] Thus we have $\triangle AFB \sim \triangle CFB \sim \triangle CFA$.  It follows that $\triangle CFB$ has a hypotenuse that is 1.5 times as long as the shorter leg and altitude $\overline{CF}$ is 1.5 times as long as the length of the shorter leg, so $\triangle CFB$ is an equilateral triangle.  We now find $a$, the side length of $\triangle CFB$, as well as the length of $b$, the hypotenuse of $\triangle CFB$, as follows: \begin{align*}
a&=\frac{6}{1.5}=4 \text{ units}\\
b &= 2a = 8 \text{ units}
\end{align*} Now we can find the area. Since $a=4,$ $\triangle CFB$ has area $\frac{1}{2}(3)(4)=6$ square units. \begin{align*}
\text{Area} & =6 + \frac{1}{2}(3)(3) +6 \\
&= \frac{1}{2}(3)(3+3+3)=\boxed{9+9\sqrt{3}} \;\text{square units}
